steps.check:
make -j16 >/dev/null 2>&1 || { echo BUILD_FAILED; exit 1; }
out=$(printf '/version\n/help\n' | HOME=$(mktemp -d) BASI_TELEMETRY=0 timeout 120 ./basi-cli --no-mcp 2>&1)
printf '%s\n' "$out" > check-output.txt
printf '%s\n' "$out" | grep -a 'BASI-CLI v0\.1' | grep -qa $'\e\[90m' || { echo NO_DIM_GREY_VERSION_LINE; exit 1; }
printf '%s\n' "$out" | grep -qaE '^\s+/version\b' || { echo NOT_IN_HELP; exit 1; }
echo PASS
